<template><AsyncState :loading="loading" :error="error"><main class="page"><PageHeader :title="t('nav.ai')"/><SectionCard :title="t('ai.status')"><StatusBadge :tone="status?.available?'success':'error'">{{status?.available?t('ai.available'):t('ai.unavailable')}}</StatusBadge><CopyableValue v-if="status?.url" :value="status.url" :copy-label="t('btn.copy')"/><p v-if="status?.model">{{t('ai.model')}}: {{status.model}}</p></SectionCard><SectionCard :title="t('ai.suggest')"><form @submit.prevent="suggest"><label>{{t('ai.suggest_placeholder')}}<input v-model.trim="tool" data-field="suggest-tool"></label><button data-action="suggest" :disabled="suggesting||!tool">{{t('ai.suggest_btn')}}</button></form><CopyableValue v-if="suggestionResult||suggestionError" :value="suggestionResult||suggestionError" :max-length="120"/></SectionCard><SectionCard :title="t('ai.diagnose')"><form @submit.prevent="diagnose"><label>{{t('ai.diagnose_placeholder')}}<textarea v-model.trim="problem" data-field="diagnose-problem"/></label><button data-action="diagnose" :disabled="diagnosing||!problem">{{t('ai.diagnose_btn')}}</button></form><CopyableValue v-if="diagnoseResult||diagnoseError" :value="diagnoseResult||diagnoseError" :max-length="120"/></SectionCard><SectionCard :title="t('ai.chat')"><label>{{t('ai.chat_placeholder')}}<textarea v-model.trim="message" data-field="chat-message" @keyup.ctrl.enter="chat"/></label><button data-action="chat" :disabled="chatting||!message" @click="chat">{{t('ai.chat_btn')}}</button><small>{{t('ai.ctrl_enter')}}</small><CopyableValue v-if="chatResult||chatError" :value="chatResult||chatError" :max-length="120"/></SectionCard></main></AsyncState></template>
<script setup>import{ref}from'vue';import AsyncState from'../components/AsyncState.vue';import CopyableValue from'../components/CopyableValue.vue';import PageHeader from'../components/PageHeader.vue';import SectionCard from'../components/SectionCard.vue';import StatusBadge from'../components/StatusBadge.vue';defineProps({t:{type:Function,required:true},status:Object,loading:Boolean,error:[String,Error],suggesting:Boolean,diagnosing:Boolean,chatting:Boolean,suggestionResult:String,suggestionError:String,diagnoseResult:String,diagnoseError:String,chatResult:String,chatError:String});const emit=defineEmits(['suggest','diagnose','chat']);const tool=ref(''),problem=ref(''),message=ref('');const suggest=()=>tool.value&&emit('suggest',tool.value);const diagnose=()=>problem.value&&emit('diagnose',problem.value);const chat=()=>message.value&&emit('chat',message.value);</script><style scoped>.page{display:grid;gap:16px;min-width:0}form,label{display:grid;gap:8px}input,textarea{max-width:100%;box-sizing:border-box}.copyable-value{max-width:100%}</style>
